9	import { spawn } from "node:child_process";
10	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
11	import { join, resolve } from "node:path";
12	import { gitEnv } from "../sandbox/index.ts";
13	import type {
14	  HarnessAttempt,
15	  HarnessDiff,
16	  HarnessErrorKind,
17	  HarnessResult,
18	  HarnessRunOptions,
