22	export const HARNESS = "claude-code";
23	export const RULES_NAME = "CLAUDE.md";
24	export const DEFAULT_ALLOWED_TOOLS = ["Edit", "Write", "Read", "Glob", "Grep", "Bash(bun test:*)", "Bash(bun test)"];
25	/** Tools that exist at all; anything else (Web*, Agent, MCP) is absent, not just denied. */
26	const TOOLS = "Bash,Edit,Write,Read,Glob,Grep";
27	
28	// Host-session plumbing that would wire the child into the parent session.
29	const SCRUB =
30	  /^(CLAUDECODE|CLAUDE_PID|CLAUDE_CODE_(SESSION_ID|HOST_SESSION_ID|CHILD_SESSION|SESSION_ATTENDED|MESSAGING_.*|ENTRYPOINT|EMIT_TOOL_USE_SUMMARIES|REPORT_FINDINGS|TERMINAL_MCP_TOOLS|ENABLE_ASK_USER_QUESTION_TOOL|SDK_HAS_HOST_AUTH_REFRESH|ENABLE_SDK_FILE_CHECKPOINTING|DESKTOP_APP_VERSION)|CLAUDE_AGENT_SDK_.*|CLAUDE_EFFORT)$/;
31	
32	export function childEnv(extra: Record<string, string | undefined> = {}): Record<string, string> {
33	  const merged = { ...process.env, ...extra };
34	  return Object.fromEntries(
35	    Object.entries(merged).filter((e): e is [string, string] => e[1] !== undefined && !SCRUB.test(e[0])),
36	  );
37	}
