39	export function claudeArgs(o: HarnessRunOptions): string[] {
40	  return [
41	    "-p", o.prompt,
42	    "--model", o.model,
43	    "--output-format", "json",
44	    "--max-turns", String(o.maxTurns),
45	    "--permission-mode", "acceptEdits",
46	    "--permission-prompts", "none",
47	    "--allowedTools", (o.allowedTools ?? DEFAULT_ALLOWED_TOOLS).join(","),
48	    "--tools", TOOLS,
49	    "--setting-sources", "project",
50	    "--strict-mcp-config",
51	    "--disable-slash-commands",
