71	/** Writes the setup's rules into the sandbox and commits it as `setup:`. Returns the setup commit. */
72	export function swapRules(sandboxPath: string, rulesFile: string | string[]): string {
73	  const files = Array.isArray(rulesFile) ? rulesFile : [rulesFile];
74	  const text = files.map((f) => readFileSync(f, "utf8")).join("\n");
75	  writeFileSync(join(sandboxPath, RULES_NAME), text);
76	  gitOk(sandboxPath, ["add", "-f", "--", RULES_NAME]);
77	  gitOk(sandboxPath, ["commit", "-q", "--allow-empty", "-m", `setup: ${RULES_NAME} from ${files.join(" + ")}`]);
78	  return gitOk(sandboxPath, ["rev-parse", "HEAD"]).trim();
79	}
