230	// ---------- entry ----------
231	export async function runClaude(o: HarnessRunOptions): Promise<HarnessResult> {
232	  const sandboxPath = resolve(o.sandboxPath);
233	  const outDir = resolve(o.outDir ?? `${sandboxPath}.out`);
234	  const args = claudeArgs(o);
235	  const bin = o.bin ?? "claude";
236	  const res: HarnessResult = {
237	    harness: HARNESS, sessionId: null, model: null, models: [], turns: null, durationMs: null, costUsd: null,
238	    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, isError: true, errorKind: null, stopReason: null,
239	    transcriptPath: null, diff: null, setupSha: null, attempts: [], command: [bin, ...args],
240	  };
241	
242	  try {
243	    mkdirSync(outDir, { recursive: true });
244	    res.setupSha = swapRules(sandboxPath, o.rulesFile);
245	  } catch (e) {
246	    res.errorKind = "setup_failed";
247	    writeFileSync(join(outDir, "error.txt"), String(e));
248	    return res;
249	  }
250	
251	  const env = childEnv(o.env);
252	  const maxRetries = o.maxRetries ?? 2;
253	  let last: Json | null = null;
254	  const setupSha = res.setupSha;
255	  for (let n = 1; ; n++) {
256	    if (n > 1) {
257	      try {
258	        resetTo(sandboxPath, setupSha);
259	      } catch (e) {
260	        writeFileSync(join(outDir, "error.txt"), String(e));
261	        break; // keep the last attempt's verdict rather than run on a dirty sandbox
262	      }
263	    }
264	    const x = await exec(bin, args, sandboxPath, env, o.timeoutMs);
265	    const j = parseResult(x.out);
266	    const apiStatus = x.timedOut ? null : apiStatusOf(j, x.err);
267	    const errorKind = errorKindOf(j, x, apiStatus);
268	    const rawPath = join(outDir, `claude.attempt-${n}.json`);
269	    writeFileSync(rawPath, j ? JSON.stringify(j, null, 2) : JSON.stringify({ stdout: x.out, stderr: x.err.slice(-4000), spawnError: x.spawnError }, null, 2));
270	    const costUsd = num(j?.total_cost_usd);
271	    res.attempts.push({ n, exitCode: x.code, timedOut: x.timedOut, wallMs: x.wallMs, isError: errorKind !== null, errorKind, apiStatus, rawPath, costUsd });
272	    if (costUsd !== null) res.costUsd = (res.costUsd ?? 0) + costUsd;
273	    const t = tokensOf(j);
274	    res.tokens = { input: res.tokens.input + t.input, output: res.tokens.output + t.output, cacheRead: res.tokens.cacheRead + t.cacheRead, cacheWrite: res.tokens.cacheWrite + t.cacheWrite };
275	    last = j;
276	    res.isError = errorKind !== null;
277	    res.errorKind = errorKind;
278	    res.transcriptPath = rawPath;
279	    if (!(errorKind !== null && retryable(apiStatus) && n <= maxRetries)) break;
280	    await sleep((o.retryBaseMs ?? 2000) * 2 ** (n - 1));
281	  }
282	
283	  const { model, models } = resolvedModel(last);
284	  res.model = model;
285	  res.models = models;
286	  res.sessionId = typeof last?.session_id === "string" ? last.session_id : null;
287	  res.turns = num(last?.num_turns);
288	  res.durationMs = num(last?.duration_ms) ?? res.attempts.at(-1)?.wallMs ?? null;
289	  res.stopReason = last?.terminal_reason ?? last?.stop_reason ?? null;
290	  writeFileSync(join(outDir, "claude.json"), readFileSync(res.transcriptPath!, "utf8"));
291	  res.transcriptPath = join(outDir, "claude.json");
292	
293	  // Partial work is still evidence: capture the diff even when the agent errored.
294	  try {
295	    res.diff = captureDiff(sandboxPath, res.setupSha, outDir);
296	  } catch (e) {
297	    writeFileSync(join(outDir, "error.txt"), String(e));
298	    if (!res.isError) {
299	      res.isError = true;
300	      res.errorKind = "setup_failed";
301	    }
302	  }
303	  return res;
304	}
