1	// Provider env for candidate setups (DESIGN.md §"Candidate generation", §"Harness adapters").
2	//
3	//   const env = providerEnv(setup, process.env);   // pass as the runClaude `env` option
4	//
5	// A setup's `env` values may hold ${VAR} references, filled from the env given here. A missing or empty
6	// variable throws with its name. Values are never printed.
7	
8	const REF = /\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g;
9	const ANTHROPIC_HOST = "api.anthropic.com";
10	
11	/** The fields of a setups/candidates/*.json file that this module reads. */
12	export interface CandidateSetup {
13	  id: string;
14	  env?: Record<string, string>;
15	}
16	
17	/**
18	 * Credentials Claude Code would send to ANTHROPIC_BASE_URL. Blanked when the base URL is not Anthropic's,
19	 * so a host key never reaches a third-party endpoint.
20	 */
21	const HOST_CREDENTIALS = ["ANTHROPIC_API_KEY"];
22	
23	function isAnthropicUrl(url: string): boolean {
24	  try {
25	    return new URL(url).hostname === ANTHROPIC_HOST;
26	  } catch {
27	    return false;
28	  }
29	}
30	
31	export function providerEnv(setup: CandidateSetup, env: Record<string, string | undefined>): Record<string, string> {
32	  const out: Record<string, string> = {};
33	  for (const [key, raw] of Object.entries(setup.env ?? {})) {
34	    out[key] = raw.replace(REF, (_, name: string) => {
35	      const v = env[name];
36	      if (v === undefined || v === "") throw new Error(`setup ${setup.id}: env var ${name} is not set (needed by ${key})`);
37	      return v;
38	    });
39	  }
40	  const base = out.ANTHROPIC_BASE_URL;
41	  if (base !== undefined && !isAnthropicUrl(base)) {
42	    for (const k of HOST_CREDENTIALS) if (!(k in out)) out[k] = "";
43	  }
44	  return out;
45	}
