1	// One contract for every harness adapter (DESIGN.md §"Replay at the parent commit", "Harness adapters").
2	// An adapter runs one replay task in a prepared sandbox and returns what grading and pricing need.
3	// Adapters never throw on agent failure: failures come back as isError + errorKind.
4	
5	export interface HarnessRunOptions {
6	  /** Sandbox repo built by src/sandbox (one base commit, no remotes). */
7	  sandboxPath: string;
8	  /** The task, as the user originally gave it. */
9	  prompt: string;
10	  /** Requested model flag. The result records the model the run actually resolved. */
11	  model: string;
12	  /** Setup rules file(s). Several paths are concatenated in order (base rules + appended rules). */
13	  rulesFile: string | string[];
14	  maxTurns: number;
15	  /** Wall-clock cap per attempt. The process group is killed when it runs out. */
16	  timeoutMs: number;
17	  /** Hard spend cap per attempt. */
18	  budgetUsd: number;
19	  /** Extra env for the child. Host-session variables are scrubbed after merging. */
20	  env?: Record<string, string | undefined>;
21	  /** Where agent.patch and the raw JSON go. Must be outside the sandbox. Default: `<sandboxPath>.out`. */
22	  outDir?: string;
23	  /** Tool allowlist. Default: the adapter's own. */
24	  allowedTools?: string[];
25	  /** Binary to run. Default: the harness name, resolved on the child's PATH. */
26	  bin?: string;
27	  /** Retries on 429/5xx only. Default 2. */
28	  maxRetries?: number;
29	  /** First backoff delay; doubles per retry. Default 2000. */
30	  retryBaseMs?: number;
31	}
32	
33	export type HarnessErrorKind =
34	  | "timeout" // wall-clock cap hit, process killed
35	  | "max_turns" // turn cap hit
36	  | "budget" // spend cap hit
37	  | "rate_limited" // 429, retries exhausted
38	  | "server_error" // 5xx, retries exhausted
39	  | "agent_error" // the harness reported is_error for another reason (auth, refusal, ...)
40	  | "unparseable_output" // exited without a result JSON
41	  | "spawn_failed" // binary missing or not executable
42	  | "setup_failed"; // rules swap or diff capture failed
43	
44	export interface HarnessTokens {
45	  input: number;
46	  output: number;
47	  cacheRead: number;
48	  cacheWrite: number;
49	}
50	
51	export interface HarnessDiff {
52	  /** `git diff --binary` of the agent's work against the `setup:` commit. */
53	  patchPath: string;
54	  filesChanged: number;
55	  added: number;
56	  removed: number;
57	  files: string[];
58	}
59	
60	export interface HarnessAttempt {
61	  /** 1-based. */
62	  n: number;
63	  exitCode: number | null;
64	  timedOut: boolean;
65	  wallMs: number;
66	  isError: boolean;
67	  errorKind: HarnessErrorKind | null;
68	  /** HTTP status when the failure was an API error, else null. */
69	  apiStatus: number | null;
70	  /** Raw output of this attempt. */
71	  rawPath: string;
